echo "▸ 0251: برهانُ 0128 يرجع صفراً — أربعُ سياساتٍ غُيّرت قصداً قبل الدفتر"
# القالبُ لا يحمل نسخةَ 0128 الإنتاجيّة لهذه الأربع، فبرهانُه صفرٌ قبل 0251 وبعدها — فحصٌ بلا زرعٍ يمرّ
# بالهجرة وبدونها. فتُحفظ نسخُ القالب لهذه الأسماء (إن وُجدت)، وتُزرع نسخةُ الإنتاج كما قيست (٢٦/١٠:
# ضاعت ٢، تغيّر شرطُ ٢): الأصلُ من 0069 و0051 و0049، وclinic_prefs_clinic_all بنمط for all، بصيغة pg_policies.
# وتُعاد نسخُ القالب كما كانت بالآخر.
T251="'delivery_orders_write','clinic_prefs_clinic_all','invoices_update','profiles_self_update','invoices_phantom_251'"
$P -c "drop table if exists _t251_saved;
       create table _t251_saved as select * from rls_policy_backup where policyname in ($T251);
       delete from rls_policy_backup where policyname in ($T251);
       delete from rls_policy_superseded where policyname in ($T251);
       insert into rls_policy_backup (migration, schemaname, tablename, policyname, permissive, roles, cmd, qual, with_check) values
       ('0128','public','delivery_orders','delivery_orders_write','PERMISSIVE','{public}','ALL','(clinic_id = auth_clinic())','(clinic_id = auth_clinic())'),
       ('0128','public','clinic_prefs','clinic_prefs_clinic_all','PERMISSIVE','{public}','ALL','(clinic_id = auth_clinic())','(clinic_id = auth_clinic())'),
       ('0128','public','invoices','invoices_update','PERMISSIVE','{public}','UPDATE','(clinic_id = auth_clinic())',
        '((clinic_id = auth_clinic()) AND ((auth_role() = ''manager''::text) OR (amount_paid = ( SELECT i.amount_paid FROM invoices i WHERE (i.id = invoices.id)))))'),
       ('0128','public','profiles','profiles_self_update','PERMISSIVE','{public}','UPDATE','(id = auth.uid())',
        '((id = auth.uid()) AND (role = ( SELECT p.role FROM profiles p WHERE (p.id = auth.uid()))))');" >/dev/null
chk "النسخةُ المزروعة تعيد ما قيس بالإنتاج: ضاعت ٢ وتغيّر شرطُ ٢ (والصلاحياتُ كما هي)" \
    "select ضاعت::text || '|' || تغير_شرطها::text || '|' || تغيرت_صلاحياتها::text from verify_rls_equivalence()" "2|2|0"
$P -f "$MIG/0251_record_old_policy_rewrites.sql" >/dev/null
chk "بعد 0251: البرهانُ صفرٌ صفرٌ صفر" \
    "select ضاعت::text || '|' || تغير_شرطها::text || '|' || تغيرت_صلاحياتها::text from verify_rls_equivalence()" "0|0|0"
chk "  والأربعُ بالدفتر بالهجرة التي غيّرتها، ونصُّها قبل التغيير منقولٌ من نسخة 0128 لا مكتوبٌ بيد" \
    "select string_agg(s.policyname || ':' || s.migration || ':' || (s.with_check is not distinct from b.with_check)::text, ',' order by s.policyname)
       from rls_policy_superseded s join rls_policy_backup b on b.policyname = s.policyname and b.migration = '0128'
      where s.policyname in ($T251)" \
    "clinic_prefs_clinic_all:0161:true,delivery_orders_write:0157:true,invoices_update:0162:true,profiles_self_update:0162:true"
$P -f "$MIG/0251_record_old_policy_rewrites.sql" >/dev/null
chk "  والإعادةُ بلا أثر" "select count(*)::text from rls_policy_superseded where policyname in ($T251)" "4"
# لا يُعفي إلا ما سمّاه: سياسةٌ خامسةٌ ضاعت تبقى ظاهرةً بعد إعادته.
$P -c "insert into rls_policy_backup (migration, schemaname, tablename, policyname, permissive, roles, cmd, qual, with_check)
       values ('0128','public','invoices','invoices_phantom_251','PERMISSIVE','{public}','SELECT','true',null);" >/dev/null
$P -f "$MIG/0251_record_old_policy_rewrites.sql" >/dev/null
chk "  وسياسةٌ خامسةٌ ضاعت لا تُعفى — البرهانُ يراها" "select ضاعت::text from verify_rls_equivalence()" "1"
# ويُدوَّن ما يختلف فعلاً وحده: سياسةٌ من الأربع نسختُها كالحيّة اليوم لا تُستثنى بلا داعٍ.
$P -c "delete from rls_policy_backup where policyname = 'invoices_phantom_251';
       delete from rls_policy_superseded where policyname = 'invoices_update';
       update rls_policy_backup b set qual = p.qual, with_check = p.with_check
         from pg_policies p where p.schemaname = 'public' and p.tablename = 'invoices' and p.policyname = 'invoices_update'
          and b.policyname = 'invoices_update' and b.migration = '0128';" >/dev/null
$P -f "$MIG/0251_record_old_policy_rewrites.sql" >/dev/null
chk "  وسياسةٌ نسختُها كالحيّة لا تُدوَّن — والبرهانُ صفرٌ بدونها" \
    "select (select count(*) from rls_policy_superseded where policyname = 'invoices_update')::text || '|' || (ضاعت + تغير_شرطها + تغيرت_صلاحياتها)::text from verify_rls_equivalence()" "0|0"
chk "  ولا تُمَسّ سياسةٌ حيّة: الأربعُ كما تركتها 0157 و0161 و0162" \
    "select count(*) filter (where policyname in ('invoices_update','profiles_self_update'))::text || '|' || count(*) filter (where policyname in ('delivery_orders_write','clinic_prefs_clinic_all'))::text from pg_policies where schemaname = 'public'" "2|0"
$P -c "delete from rls_policy_backup where policyname in ($T251);
       delete from rls_policy_superseded where policyname in ($T251);
       insert into rls_policy_backup overriding system value select * from _t251_saved;
       drop table _t251_saved;" >/dev/null
chk "  والقالبُ رجع كما كان: البرهانُ صفر" \
    "select (ضاعت + تغير_شرطها + تغيرت_صلاحياتها)::text from verify_rls_equivalence()" "0"

# ── 0252: مستهلكاتُ الخدمات — الوصفةُ تخصم وتكلّف بالخادم، وكلُّ عكسٍ يردّها بالضبط ─────────────
# كلُّ رقمٍ هنا محسوبٌ باليد قبل التشغيل: الرصيدُ بثلاث منازل، والمرحَّلُ بتسع، والمالُ بمنزلتين.
# مفتاحُ الحساب: T(Q) = Q·الكمية/القسمة بتسع منازل، وw = الكمية·الكلفة/القسمة بمنزلتين، والمكتوبُ بالرصيد
# تقريبُ **المجموع التراكميّ** للأعلى عند النصف — فـ١٠ مل من مكعّب ٢٠٠٠٠ مل = ٠٫٠٠٠٥: الأولى تكتب ٠٫٠٠١
# (المرحَّل −٠٫٠٠٠٥) والثانيةُ صفراً (المرحَّل صفر)، والترجيعُ يردّ بالضبط ما أخذ.
# الكتابةُ بطلبٍ والقراءةُ بآخر (اللقطة)، وكلُّ ما يُتوقَّع رفضُه يمرّ من _rls_try/_pf_try (set -e)، وكلُّ
# كتابةٍ بدور authenticated فعلاً (RLS والمنح كالإنتاج). وبعد كلّ خطوةِ عكس: verify_consumption() نظيف —
# الحيُّ = T(الهدف)، وثابتُ المرحَّل، ولا سطرَ حيٌّ تحت كلفة موادّه.
# الصفوفُ كلُّها من هذا القسم (البادئة a2520000-…)، وعيادتان منفصلتان للترتيب والتقرير (أرقامٌ لا يمسّها غيرُها).
echo "▸ 0252: مستهلكاتُ الخدمات — الوصفةُ تخصم وتكلّف بالخادم، وكلُّ عكسٍ يردّها بالضبط"
C1=11111111-1111-1111-1111-111111111111
C2=22222222-2222-2222-2222-222222222222
ADM=33333333-3333-3333-3333-333333333333
VET=55555555-5555-5555-5555-555555555555
RCP=77777777-7777-7777-7777-777777777777
PHO=88888888-8888-8888-8888-888888888888
R=a2520000-0000-4000-8000-0000000000
CR=${R}d0; VR=${R}d1; CT=${R}e0; RS=${R}82
ZID=00000000-0000-0000-0000-000000000000
CC='collate "C"'
E0=d41d8cd98f00b204e9800998ecf8427e   # md5('') — بصمةُ وصفةٍ فارغة

# 0252 ثم كلُّ هجرةٍ بعدها بالموجة وبترتيبها. الأقسامُ قبلنا أعادت 0241 و0242 (فرجع جسمُ البيعة والتعديل
# والحركات لنصّها القديم)، والمنحُ الشامل (0159) فتح الأدواتِ الداخلية للداخلين — فتُعاد 0252 لتغلبهما،
# ثم ما بعدها (0253/0254/0255 تعيد تعريفَ بعضِ ما أعادته 0252) ليرجع آخرُ جسمٍ لكلّ دالّة: حالُ الإنتاج.
_m0252() {
  local f n out
  out=$($P -f "$MIG/0252_service_consumption.sql" 2>&1) || { echo "$out"; echo "   ✗ 0252 ما انعادت"; fail=1; }
  for f in $WAVE; do
    n=$(basename "$f"); n=${n%%_*}
    if [[ "$n" > "0252" ]]; then
      out=$($P -f "$f" 2>&1) || { echo "$out"; echo "   ✗ $(basename "$f") ما انعادت بعد 0252"; fail=1; }
    fi
  done
}
_m0252

# ── أدواتُ القسم ──
# rt: نصٌّ يُنفَّذ بدور authenticated ⇒ rows:N أو guarded:SQLSTATE:الرسالة. rerr: رمزُ الرفض وحده.
# rv: قيمةٌ بدور authenticated (أو guarded:…) — الاستخراجُ داخل الاستعلام المنفَّذ، فالفشلُ نصٌّ لا خطأٌ يوقف الحزمة.
rt()   { echo "_rls_try('$1', \$q\$$2\$q\$)"; }
rerr() { echo "split_part(_rls_try('$1', \$q\$$2\$q\$), ':', 3)"; }
rv()   { echo "_v0252('$1', \$q\$$2\$q\$)"; }
inv()  { echo "(select id from invoices where clinic_id = '${2:-$C1}' and client_ref = '$1' limit 1)"; }
li()   { echo "(select id from invoice_items where invoice_id = $(inv "$1" "${3:-$C1}") and name = '$2' order by id limit 1)"; }
co()   { echo "select retail_checkout('$2'::jsonb, jsonb_build_object('client_ref', '$1')${3:+ || $3})"; }
stk()  { local e="" id; for id in "$@"; do e="$e${e:+||'|'||}coalesce((select stock::text from products where id = '$id'), 'gone')"; done; echo "$e"; }
cry()  { echo "coalesce((select carry::text from product_stock_carry where product_id = '$1'), 'none')"; }
vc()   { chk "${1:-  والدفترُ متّسق (verify_consumption نظيف)}" \
             "select coalesce(string_agg(\"check\" || '@' || coalesce(product_id::text, item_id::text, '-'), ';' order by \"check\", product_id, item_id), 'clean') from verify_consumption()" "clean"; }

$P -c "create or replace function _v0252(who uuid, q text) returns text language plpgsql as \$fn\$
       declare r text; begin
         perform set_config('request.jwt.claim.sub', who::text, true);
         set local role authenticated;
         execute q into r;
         reset role;
         return coalesce(r, '-');
       exception when others then return 'guarded:' || sqlstate || ':' || sqlerrm; end \$fn\$;
       delete from staff_elevations; update _dvtest_flags set admin = false; delete from platform_sessions;
       insert into auth.users(id) values ('$VET'), ('$RCP'), ('$PHO'), ('$RS'), ('$CR'), ('$VR'), ('$CT') on conflict do nothing;
       insert into memberships(user_id, clinic_id, role, status)
         select v.u::uuid, v.c::uuid, v.r, 'active'
           from (values ('$VET','$C1','veterinarian'), ('$RCP','$C1','receptionist'), ('$PHO','$C1','photographer'),
                        ('$RS','$C1','receptionist'), ('$VR','$CR','veterinarian')) v(u, c, r)
          where not exists (select 1 from memberships m where m.user_id = v.u::uuid);
       insert into staff(id, clinic_id, name, user_id, role, permissions) values
         ('${R}83', '$C1', 'استقبال الوصفات', '$RS', 'receptionist', '{\"manageSettings\": true}'),
         ('${R}d2', '$CR', 'طبيب الوصفة', '$VR', 'veterinarian', '{}')
         on conflict (id) do nothing;
       -- تدقيقُ المنتجات والخدمات بشكل الإنتاج (audit_all، 0044/0045) — حركاتُ المادة تُقرأ منه.
       drop trigger if exists audit_all on products;
       create trigger audit_all after insert or update or delete on products for each row execute function audit_change();
       drop trigger if exists audit_all on clinic_services;
       create trigger audit_all after insert or update or delete on clinic_services for each row execute function audit_change();" >/dev/null

