    "select coalesce(counted_by::text,'null')||'|'||coalesce(counted_by_name,'null')||'|'||status||'|'||coalesce(decided_by_name,'null')||'|'||(select stock::text from products where id = '$w30') from stock_counts where product_id = '$w30'" \
