    "select coalesce((select (md5(regexp_replace(prosrc, '[ \t\n\r\f\v]', '', 'g')) = '5b33e0eb915538897cf01a929a34fa26')::text from pg_proc where oid = to_regprocedure('public.invoice_consumption_get(uuid[])')), 'missing')
