bq254b=$(W "select coalesce(string_agg(z.b::text, ','), '') from (select distinct $US254 b from invoice_consumption c where c.invoice_id::text = '$fq254' and c.kind = 'restore') z where z.b > $(nb254 "$bq254a")")
