DC=${DG}c1
DR=${DG}c2
DO=${DG}c3
rt()   { echo "_rls_try('$1', \$q\$$2\$q\$)"; }
rerr() { echo "split_part(_rls_try('$1', \$q\$$2\$q\$), ':', 3)"; }
rv()   { echo "_v0252('$1', \$q\$$2\$q\$)"; }
