    "select $(rv $OC "select coalesce(sum(invoices), 0)::text||':'||coalesce(sum(revenue), 0)::bigint from report_staff($RNG)")||'|'||$(rv $OC "select count(*)::text from report_top_products($RNG, 50)")" "1:1000|1"
