    "select (select stock::text from products where id = '${UG}a1')||'|'||(select string_agg(qty::text||'/'||stock_qty::text||':'||coalesce(unit_label,'-')||'@'||unit_price_usd::text||'~'||unit_cost_usd::text||'~'||unit_cost::text, ',' order by stock_qty desc)
