            ||'|'||$(rerr $DV "$(DFX '[{"name":"كشف","qty":1,"unit_price":1460,"unit_cost":0,"price_currency":"USD","unit_price_usd":1}]' "$(DMETA d282-r8 "$DRID" 1460)")")" \
