         ('${R}f3','$C1','${R}f2','${R}f0','محلول التراجع',10,'sub',0), ('${R}f4','$C1','${R}f2','${R}f1','قطعة التراجع',1,'sub',1)
         on conflict (id) do nothing;" >/dev/null
