for _ in 1 2 3; do
  $P -c "select _as287('$C1', \$q\$select (purchase_record_once('R287-P1', '$L87'::jsonb, '{\"amount_paid\":0}'::jsonb, false)).id::text\$q\$);" >/dev/null
done
