    "select _as287('$C1', \$q\$select string_agg(product_id::text || ':' || ledger_qty::text || '/' || live_qty::text, ',' order by product_id) from verify_stock_ledger()\$q\$)" \
    "${P87}8:0/5.000,${P87}9:1.000/8.000"
