            ||'|'||split_part(_u294('${UN}14', true, false, null, 100, 50, 0, null, 10, 1, '$K94'), ':', 2)
            ||'|'||split_part(_u294('${UN}15', true, false, null, 100, 50, 0, null, 10, 1, '$K94'), ':', 2)" \
